import{_ as a,o as t,c as s,a6 as o}from"./chunks/framework.O8w_gp-L.js";const c=JSON.parse('{"title":"Stages, chapters and stars","description":"","frontmatter":{},"headers":[],"relativePath":"guides/stages-and-chapters.md","filePath":"guides/stages-and-chapters.md"}'),r={name:"guides/stages-and-chapters.md"};function n(l,e,i,h,g,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="stages-chapters-and-stars" tabindex="-1">Stages, chapters and stars <a class="header-anchor" href="#stages-chapters-and-stars" aria-label="Permalink to &quot;Stages, chapters and stars&quot;">​</a></h1><h2 id="the-story-so-far" tabindex="-1">The story so far <a class="header-anchor" href="#the-story-so-far" aria-label="Permalink to &quot;The story so far&quot;">​</a></h2><p>Sir Lackluster cut the threads that tie each place to Loomhaven, and every keeper went wild. Calm each boss to mend its thread.</p><h2 id="five-chapters-to-play" tabindex="-1">Five chapters to play <a class="header-anchor" href="#five-chapters-to-play" aria-label="Permalink to &quot;Five chapters to play&quot;">​</a></h2><ul><li><strong>Chapter 1, Canal Towpath (Lv 1-8):</strong> Water Gate Steps, Dyers Wharf, Lock Stairs, Millwheel Weir, Gooseneck Ferry Lock. Boss: <strong>Captain Gooseneck</strong></li><li><strong>Chapter 2, Fireflyfen Bayou (Lv 10-14):</strong> Reedwater Landing, Reedstilt Hamlet, Moonlily Pools, Drowned Paddle Steamer, Croakwell&#39;s Stilthouse. Boss: <strong>Granny Croakwell</strong></li><li><strong>Chapter 3, Rootbound Archive (Lv 16-19):</strong> Mossdoor Threshold, Candlewick Reading Hall, Inkspring Hollows, Leaflight Bindery, Hushwing Crown Loft. Boss: <strong>Mother Hushwing</strong></li><li><strong>Chapter 4, Ember Boilerworks Terraces (Lv 21-25):</strong> Rootmouth Tea Steps, Jadewater Pools, Whistleclock Row, Lava Kiln Bridges, Great Boiler Summit. Boss: <strong>the Steamkeeper</strong></li><li><strong>Chapter 5, Frostbell Peaks (Lv 26-30):</strong> Thawline Springs, Great Mug Inn Pass, Frozen Falls Bridge, Courtyard of Vows, Summit of the Bell. Boss: <strong>Old Yeti Yarn</strong> Chapters 6 to 12 come in later updates.</li></ul><h2 id="how-stages-open" tabindex="-1">How stages open <a class="header-anchor" href="#how-stages-open" aria-label="Permalink to &quot;How stages open&quot;">​</a></h2><p>Clear a stage to open the next one.</p><h2 id="boss-keepsakes" tabindex="-1">Boss keepsakes <a class="header-anchor" href="#boss-keepsakes" aria-label="Permalink to &quot;Boss keepsakes&quot;">​</a></h2><p>2 on your first clear, and sometimes 1 on a repeat clear: Captain&#39;s Brass Button, Lily Brooch, Hushwing&#39;s Spectacles, Boiler Gauge Glass, Summit Bell Cord.</p><h2 id="stars" tabindex="-1">Stars <a class="header-anchor" href="#stars" aria-label="Permalink to &quot;Stars&quot;">​</a></h2><p>Each stage has three:</p><ul><li><strong>Clear the stage</strong></li><li><strong>Under</strong> the par time</li><li>Land the stage&#39;s <strong>hit combo</strong> Three stars pays more materials. Earn <strong>15 stars</strong> (all of chapter 1 is enough) and forge a weapon to unlock the <strong>starlit look</strong> at the Forge.</li></ul><h2 id="the-summit-gate" tabindex="-1">The summit gate <a class="header-anchor" href="#the-summit-gate" aria-label="Permalink to &quot;The summit gate&quot;">​</a></h2><p><strong>5-5 Summit of the Bell</strong> only starts after you take your <strong>second vow</strong>. Your first Normal clear of 5-5 gives a <strong>band-30 armour kit</strong>: pick one piece to forge. You get one pick.</p><p><strong>Lives:</strong> playing alone, you get <strong>3 lives</strong>. A knockout stands you back up where you fell.</p>',15)])])}const u=a(r,[["render",n]]);export{c as __pageData,u as default};
